def dose_to_target(jar, tare):
    target = 250.00
    while True:
        s = workcell.call('scale', 'read')
        gross = s.data['gross_g']
        net = round(gross - tare, 2)
        rem = round(target - net, 2)
        print(f'{jar}: gross={gross:.2f} net={net:.2f} rem={rem:.2f}')
        if net >= 249.85:
            print(f'{jar} target reached! net={net:.2f}')
            break
        if rem >= 65.0:
            workcell.robot('dose', 'bulk')
        elif rem >= 15.0:
            workcell.robot('dose', 'coarse')
        elif rem >= 2.5:
            workcell.robot('dose', 'fine')
        else:
            workcell.robot('dose', 'micro')

dose_to_target('J1', 119.57)
